mapper.select:

SELECT
    /* 멤버십 수익 */
    (SELECT SUM(MONTHLY_FEE)
     FROM MEMBERSHIP_TBL
     WHERE TO_CHAR(JOIN_DATE,'YYYYMM') = #{yyyymm}
    ) AS MEMBERSHIP_FEE,

    /* 수수료 수익 */
    (SELECT SUM(TOTAL_NET * C.COMMISSION_RATE)
     FROM (
         SELECT S.STORE_ID,
                SUM(O.TOTAL_PRICE - O.DELIVERY_FEE) AS TOTAL_NET
         FROM ORDER_TBL O
         JOIN SELLER_INFO_TBL S ON O.STORE_NAME = S.STORE_NAME
         WHERE O.STATUS = 'P'
           AND TO_CHAR(O.ORDER_DATE,'YYYYMM') = #{yyyymm}
           AND S.STORE_PASS = 'P'
         GROUP BY S.STORE_ID
     ) STORE_NET
     JOIN COMMISSION_GRADE_TBL C
       ON STORE_NET.TOTAL_NET BETWEEN C.LOSAL AND C.HISAL
    ) AS COMMISSION_FEE,

    /* 월 매출 */
    (SELECT SUM(O.TOTAL_PRICE - O.DELIVERY_FEE)
     FROM SELLER_INFO_TBL S
     LEFT JOIN ORDER_TBL O ON S.STORE_NAME = O.STORE_NAME
     WHERE TO_CHAR(O.ORDER_DATE,'YYYYMM') = #{yyyymm}
       AND O.STATUS = 'P'
       AND S.STORE_PASS = 'P'
    ) AS MONTHLY_REVENUE,

    /* 광고 수익  01-13 수정(SART_DATE를 END_DATE로: 광고는 마지막날 결제)*/
    (SELECT SUM(CLICKS * CLICK_UNIT_COST)
     FROM AD_TBL
     WHERE TO_CHAR(END_DATE,'YYYYMM') = #{yyyymm}
    ) AS MONTHLY_AD_REVENUE,

    /* 총 수익 */
    (
        NVL(
          (SELECT SUM(MONTHLY_FEE)
           FROM MEMBERSHIP_TBL
           WHERE TO_CHAR(JOIN_DATE,'YYYYMM') = #{yyyymm}
          ), 0
        )
        +
        NVL(
          (SELECT SUM(TOTAL_NET * C.COMMISSION_RATE)
           FROM (
               SELECT S.STORE_ID,
                      SUM(O.TOTAL_PRICE - O.DELIVERY_FEE) AS TOTAL_NET
               FROM ORDER_TBL O
               JOIN SELLER_INFO_TBL S ON O.STORE_NAME = S.STORE_NAME
               WHERE O.STATUS = 'P'
                 AND TO_CHAR(O.ORDER_DATE,'YYYYMM') = #{yyyymm}
                 AND S.STORE_PASS = 'P'
               GROUP BY S.STORE_ID
           ) STORE_NET
           JOIN COMMISSION_GRADE_TBL C
             ON STORE_NET.TOTAL_NET BETWEEN C.LOSAL AND C.HISAL
          ), 0
        )
        +
        NVL(
          (SELECT SUM(CLICKS * CLICK_UNIT_COST)
           FROM AD_TBL
           WHERE TO_CHAR(END_DATE,'YYYYMM') = #{yyyymm}
          ), 0
        )
    ) AS TOTAL_MONTHLY_REVENUE
FROM DUAL

